impl std::ops::Deref for Label {
    type Target = ContentControl;
    fn deref(&self) -> &Self::Target {
        unsafe { &*(self as *const Self as *const Self::Target) }
    }
}

unsafe impl crate::Upcast<AvaloniaObject> for Label {
    fn upcast(&self) -> AvaloniaObject {
        AvaloniaObject {
            raw: unsafe { self.raw.cast_clone() },
        }
    }
    fn upcast_ref(&self) -> &AvaloniaObject {
        unsafe { &*(self as *const Self as *const AvaloniaObject) }
    }
}

impl AsRef<AvaloniaObject> for Label {
    fn as_ref(&self) -> &AvaloniaObject {
        <Self as crate::Upcast<AvaloniaObject>>::upcast_ref(self)
    }
}

unsafe impl crate::Downcast<Label> for AvaloniaObject {
    fn is_instance(&self) -> bool {
        self.raw.query_interface::<sys::IAvnLabel>().is_ok()
    }
    fn downcast(&self) -> Option<Label> {
        self.raw
            .query_interface::<sys::IAvnLabel>()
            .ok()
            .map(|raw| Label { raw })
    }
}

